const original=$('POST Dental Lab AI').first();
const b=$json.body??$json;
const bins=original.binary??{};
const first=Object.keys(bins)[0]??null;
let mime="",binary={};
if(first){
  const x=bins[first];
  mime=String(x.mimeType??x.fileType??"").toLowerCase();
  binary={data:x};
}
const authHeader=String(original.json?.headers?.authorization??original.json?.headers?.Authorization??"").trim();
let input_type=String(b.input_type??b.type??"").toLowerCase();
if(!input_type){
  if(mime.startsWith("image/"))input_type="image";
  else if(mime.startsWith("audio/")||mime.includes("webm")||mime.includes("ogg")||mime.includes("wav")||mime.includes("mpeg"))input_type="audio";
  else input_type="text";
}
let pending=b.pending_operation??null;
if(typeof pending==="string"){
  try{pending=JSON.parse(pending);}catch{pending=null;}
}
if(!pending||typeof pending!=="object"||Array.isArray(pending))pending=null;
const sessionId=String(b.session_id??"default");
return [{json:{
  input_type,
  user_text:String(b.text??b.message??b.prompt??"").trim(),
  session_id:sessionId,
  client_request_id:String(b.client_request_id??`${sessionId}-${Date.now()}`),
  pending_operation:pending,
  auth_header:authHeader,
  today:new Date().toLocaleDateString("en-CA",{timeZone:"Europe/Bucharest"})
},binary}];

const input=$('AI - Unified').first().json;
// Named, not positional: this node used to sit directly after the
// Bootstrap call, so $json was the bootstrap payload. It now runs after
// AI - Unified, and $json would be the merged request instead -- which
// made b.allowed undefined and this blocked-check quietly stop firing.
const b=$('Supabase - AI Bootstrap').first().json;

if(b?.allowed===false){
  return [{json:{
    blocked:true,
    reply:b?.message||"AI is not available for this role.",
    input,
    bootstrap:b
  }}];
}

const role=String(b.role||"").toLowerCase();
const catalog=Array.isArray(b.catalog)?b.catalog:[];

const rules=role==="technician"
? `TECHNICIAN DATA ACCESS IS STRICTLY LIMITED.
You may retrieve ONLY:
- my_work_orders
- my_receivables
- work_types
- materials_inventory
- calendar_events
Never request users, patient cases, partner commercial data, client prices, discounts, contracts, relationship terms/prices, other technicians' costs, files, chat history or any other dataset.
For a Technician financial summary by partner, retrieve my_receivables. Its By_Partner totals are the technician's own compensation and do not require client sale prices.
Technician may CREATE a new Work Order and UPDATE configured tooth items for a Work Order they can access through AI, but cannot DELETE through AI.`
: `ADMIN/MANAGER AI MAY READ ANY DATASET LISTED IN THE CATALOG.
The catalog intentionally excludes credentials/secrets/password hashes/tokens.
Choose only the datasets needed to answer the question.
For a broad cross-business question you may request multiple datasets.`;

const prompt=`You are the data retrieval planner for Flowrise Dental AI.

ROLE: ${role}

${rules}

For questions or edits about solidarizati/solidarizați, solo, bridges or tooth connections, retrieve existing clinical tooth details before editing links. Technician: my_work_orders includes Tooth_Details. Admin/Manager: retrieve patient_cases plus work_orders for the requested IDs. Never infer current links from tooth colors or work types.

USER QUESTION:
${input.normalized_text}

AVAILABLE DATASETS:
${JSON.stringify(catalog)}

RECENT CHAT:
${JSON.stringify(b.history||[])}

Return ONLY valid JSON:
{
  "datasets":["dataset_name"],
  "limit":1000,
  "reason":"short reason"
}

Rules:
- datasets must come EXACTLY from AVAILABLE DATASETS.
- use [] only if the question can be answered without any Supabase business data.
- maximum 8 datasets for a normal question.
- use limit between 1 and 5000.
- for Technician, use only my_work_orders, my_receivables, work_types, materials_inventory and/or calendar_events.
- a Technician request for a financial summary by partner MUST use my_receivables; never request or claim that relationship_prices are needed.
- for Admin/Manager financial summaries by partner, use work_orders and contract_prices; relationship_prices is not the legacy price list.
- do not answer the user yet.`;

return [{json:{blocked:false,prompt,input,bootstrap:b}}];

return [{json:{
  type:"answer",
  intent:"answer",
  reply:String($json.reply||"AI is not available for this role."),
  session_id:$('AI - Unified').first().json.session_id
}}];

let raw=$json.text??$json.output??$json.response??"";
if(typeof raw!=="string")raw=JSON.stringify(raw);
raw=raw.trim().replace(/^```json\s*/i,"").replace(/^```\s*/i,"").replace(/\s*```$/,"");

let plan={datasets:[],limit:1000};
try{plan=JSON.parse(raw);}catch{}

const bootstrap=$('Supabase - AI Bootstrap').first().json;
const allowed=new Set((bootstrap.catalog||[]).map(x=>String(x.dataset)));
let datasets=Array.isArray(plan.datasets)?plan.datasets.map(String).filter(x=>allowed.has(x)):[];
datasets=[...new Set(datasets)].slice(0,bootstrap.role==="technician"?5:20);

let limit=Number(plan.limit||1000);
if(!Number.isFinite(limit))limit=1000;
limit=Math.max(1,Math.min(5000,Math.round(limit)));

return [{json:{
  datasets,
  limit,
  role:String(bootstrap.role||""),
  session_id:$('AI - Unified').first().json.session_id
}}];

let raw=$json.text??$json.output??$json.response??"";
if(typeof raw!=="string")raw=JSON.stringify(raw);
raw=raw.trim();
const fence=String.fromCharCode(96).repeat(3);
if(raw.startsWith(fence)){
  raw=raw.slice(fence.length).replace(/^json\s*/i,"").replace(new RegExp("\\s*"+fence+"$"),"");
}
let plan;
try{plan=JSON.parse(raw);}catch{plan={intent:"answer",reply:raw||"Nu am putut interpreta răspunsul AI.",payload:{}};}
const input=$('AI - Unified').first().json;
const role=String($('Supabase - AI Bootstrap').first().json.role||"").toLowerCase();
const pending=input.pending_operation&&typeof input.pending_operation==="object"?input.pending_operation:null;
let intent=String(plan.intent||"answer").toLowerCase();
if(!["answer","clarify","preview","execute","create","update","delete"].includes(intent))intent="answer";
let payload=plan.payload&&typeof plan.payload==="object"&&!Array.isArray(plan.payload)?plan.payload:{};
let operation=plan.operation&&typeof plan.operation==="object"&&!Array.isArray(plan.operation)?{...plan.operation}:{};
let operationEntity=String(operation.entity||"").toLowerCase();
const workOrderFields=new Set(["Nume_Pacient","Nume_Partener","items","case","Deadline","Data_Receptie","Contract","Status","Discount","Tehnician_Model","Tehnician1_Modelare","Tehnician2_Cer_Fin","Status_Model","Status_Modelare","Status_Cer_Fin","Paid_Model","Paid_Modelare","Paid_Cer_Fin","Settlement_Model","Settlement_Modelare","Settlement_Cer_Fin","Locked","Model_Not_Applicable","Modelare_Not_Applicable","Cer_Fin_Not_Applicable","My_Stage"]);
const isObject=value=>value&&typeof value==="object"&&!Array.isArray(value);
const validToothItems=items=>Array.isArray(items)&&items.length>0&&items.every(item=>{
  const tooth=Number(item?.tooth_number);
  return isObject(item)&&Number.isInteger(tooth)&&tooth>=11&&tooth<=48&&tooth%10>=1&&tooth%10<=8&&typeof item.work_type==="string"&&item.work_type.trim()!=="";
});
const sanitizeClinicalDetails=value=>{
  if(Array.isArray(value))return value.map(sanitizeClinicalDetails);
  if(!isObject(value))return value;
  return Object.fromEntries(Object.entries(value)
    .filter(([key])=>!["material","tip_lucrare","nr_elemente"].includes(String(key).toLowerCase()))
    .map(([key,child])=>[key,sanitizeClinicalDetails(child)]));
};
const clinicalCaseFields=new Set(["tooth_details","tooth_details_json","clinic_note","shade","method","production_notes"]);
const clinicalToothDetails=caseData=>{
  let details=caseData.tooth_details??caseData.tooth_details_json;
  if(typeof details==="string"){
    if(Object.prototype.hasOwnProperty.call(caseData,"tooth_details"))throw new Error("tooth_details must be an object");
    details=JSON.parse(details);
  }
  if(!isObject(details)||Object.entries(details).some(([key,value])=>(key!=="__case"&&!/^[1-4][1-8]$/.test(key))||!isObject(value)))
    throw new Error("Tooth details must map FDI numbers or __case to objects");
  details=sanitizeClinicalDetails(details);
  if(details.__case&&Object.prototype.hasOwnProperty.call(details.__case,"tooth_connections")){
    const arches=[[18,17,16,15,14,13,12,11,21,22,23,24,25,26,27,28],[48,47,46,45,44,43,42,41,31,32,33,34,35,36,37,38]];
    const pairs=arches.flatMap(arch=>arch.slice(1).map((t,i)=>[arch[i],t]));
    const keys=new Map(pairs.flatMap((pair,i)=>[[pair.join("-"),i],[[...pair].reverse().join("-"),i]]));
    const connections=details.__case.tooth_connections;
    if(!Array.isArray(connections)||connections.some(pair=>!Array.isArray(pair)||pair.length!==2||!pair.every(Number.isInteger)||!keys.has(pair.join("-"))))
      throw new Error("Connections must be adjacent FDI pairs in the same arch");
    const indices=new Set(connections.map(pair=>keys.get(pair.join("-"))));
    details.__case.tooth_connections=pairs.filter((pair,i)=>indices.has(i));
  }
  return details;
};
const validClinicalCase=caseData=>{
  if(!isObject(caseData)||Object.keys(caseData).some(key=>!clinicalCaseFields.has(key)))return false;
  if("tooth_details" in caseData&&"tooth_details_json" in caseData)return false;
  for(const key of ["clinic_note","shade","method","production_notes"])
    if(key in caseData&&caseData[key]!==null&&typeof caseData[key]!=="string")return false;
  if("tooth_details" in caseData||"tooth_details_json" in caseData){
    try{clinicalToothDetails(caseData);}catch{return false;}
  }
  return true;
};
const canonicalizeWorkOrderFields=fields=>{
  const canonical={...fields};
  if(Array.isArray(fields.items))canonical.items=fields.items.map(item=>({
    tooth_number:Number(item.tooth_number),
    work_type:item.work_type.trim()
  }));
  if(isObject(fields.case)){
    canonical.case={...fields.case};
    if("tooth_details" in fields.case||"tooth_details_json" in fields.case){
      delete canonical.case.tooth_details_json;
      canonical.case.tooth_details=clinicalToothDetails(fields.case);
    }
  }
  return canonical;
};
const invalidWorkOrderFields=(fields,requiresItems)=>{
  if(!isObject(fields))return true;
  if(Object.keys(fields).some(key=>!workOrderFields.has(key)))return true;
  if(requiresItems&&!validToothItems(fields.items))return true;
  if(Object.prototype.hasOwnProperty.call(fields,"items")&&!validToothItems(fields.items))return true;
  if(Object.prototype.hasOwnProperty.call(fields,"case")&&!validClinicalCase(fields.case))return true;
  if(Array.isArray(fields.items)&&isObject(fields.case)&&("tooth_details" in fields.case||"tooth_details_json" in fields.case)){
    const connections=clinicalToothDetails(fields.case).__case?.tooth_connections||[];
    const scope=new Set(fields.items.map(item=>Number(item.tooth_number)));
    if(connections.some(pair=>pair.some(t=>!scope.has(t))))return true;
  }
  return false;
};
const rejectWorkOrder=()=>{
  intent="clarify";
  plan.reply="Pentru această lucrare am nevoie de cel puțin un dinte configurat, fiecare cu număr FDI și tip de lucrare. Cazul acceptă clinic_note, shade, method, production_notes și tooth_details sau tooth_details_json, un obiect indexat după numărul dintelui. Legăturile tooth_connections trebuie să conțină perechi de dinți vecini din aceeași arcadă, incluși în lucrare. Tipul general, materialul clinic și numărul de elemente nu se folosesc.";
  payload={};operation={};operationEntity="";
};

if(intent==="execute"&&pending?.preview_id&&operation.preview_id){
  if(String(operation.preview_id||"")===String(pending.preview_id)){
    operation={...pending};
    operationEntity=String(operation.entity||"").toLowerCase();
  }else{
    intent="clarify";
    plan.reply="Confirmarea nu corespunde operației pregătite. Te rog confirmă folosind codul afișat sau cere o previzualizare nouă.";
    operation={};operationEntity="";
  }
}
if(["create","update"].includes(intent)&&invalidWorkOrderFields(payload.fields,intent==="create"))rejectWorkOrder();
else if(["create","update"].includes(intent))payload={...payload,fields:canonicalizeWorkOrderFields(payload.fields)};
if(["preview","execute"].includes(intent)){
  operation.entity=String(operation.entity||"").toLowerCase();
  operation.operation=String(operation.operation||"").toLowerCase();
  operation.target=isObject(operation.target)?operation.target:{};
  operation.fields=isObject(operation.fields)?operation.fields:{};
  operationEntity=operation.entity;
  if(operationEntity==="work_order"&&["create","update"].includes(operation.operation)&&invalidWorkOrderFields(operation.fields,operation.operation==="create"))rejectWorkOrder();
  else if(operationEntity==="work_order"&&["create","update"].includes(operation.operation))operation.fields=canonicalizeWorkOrderFields(operation.fields);
}
const billingModes=new Set(["per_tooth","per_arch","per_piece"]);
if(["preview","execute"].includes(intent)&&operationEntity==="work_type"&&["create","update"].includes(operation.operation)){
  const hasMode=Object.prototype.hasOwnProperty.call(operation.fields,"billing_mode");
  const mode=String(operation.fields.billing_mode??"").trim().toLowerCase();
  if(hasMode&&!billingModes.has(mode)){
    intent="clarify";
    plan.reply="Modul de facturare trebuie să fie per_tooth, per_arch sau per_piece.";
    operation={};operationEntity="";
  }else if(hasMode||operation.operation==="create"){
    operation.fields.billing_mode=hasMode?mode:"per_tooth";
  }
}
if(role==="technician"&&(["delete"].includes(intent)||(["preview","execute"].includes(intent)&&!["material","calendar_event"].includes(operationEntity)))){
  intent="clarify";
  plan.reply="Pot crea sau actualiza dinții configurați pentru lucrările la care am acces și pot oferi statusul lucrărilor mele sau sumele mele de încasat, dar această modificare nu este permisă pentru rolul Tehnician.";
  payload={};operation={};
}
if(role==="manager"&&["preview","execute"].includes(intent)&&!["material","calendar_event"].includes(operationEntity)){
  intent="clarify";
  plan.reply="Această modificare de configurare este disponibilă doar pentru rolul Admin.";
  payload={};operation={};
}
if(["preview","execute"].includes(intent)){
  operation.request_key=String(input.client_request_id||input.session_id+"-"+Date.now());
}
return [{json:{intent,reply:String(plan.reply||""),payload,operation,role,session_id:input.session_id}}];

const db=$json;
const plan=$('AI - Parse Final').first().json;
if(!db?.ok){
  const error=String(db?.error||"operația a fost refuzată de Supabase.");
  const clearPending=/preview.*(missing|expired|used|stale)/i.test(error);
  return [{json:{type:"answer",intent:"clarify",reply:`Nu am aplicat modificarea: ${error}`,clear_pending:clearPending,session_id:plan.session_id}}];
}
if(plan.intent==="preview"){
  const sourceCount=Array.isArray(db.before?.source)?db.before.source.length:null;
  const directCount=Array.isArray(db.before)?db.before.length:null;
  const count=sourceCount??directCount??db.count??"";
  return [{json:{type:"preview",intent:"clarify",reply:`${plan.reply||"Confirmi această modificare?"}\n\nCod confirmare: ${db.preview_id}${count!==""?` · ${count} înregistrări afectate`:""}`,pending_operation:{...plan.operation,preview_id:db.preview_id},mutation:db,session_id:plan.session_id}}];
}
return [{json:{type:String(db.type||`${plan.operation?.entity||plan.intent}_${plan.operation?.operation||plan.intent}`),intent:plan.intent,reply:plan.reply||`Modificarea a fost aplicată (${db.count??1} înregistrări).`,mutation:db,session_id:plan.session_id}}];

// Re-emit the normalized request, binary included.
//
// The HTTP node above replaced the item with Supabase's response, but
// the router switches on input_type and the image and audio nodes need
// the uploaded file. Reaching back to the named node is what keeps the
// branches working after the gate was moved in front of them.
const src = $('AI - Normalize Input').first();
return [{ json: src.json, binary: src.binary }];
